(174169, 9818, 3859, '<td valign="top">You work for Allstate?  Just kidding, I love this concept but I wish it were a bit lighter.</td>', 'You work for Allstate?  Just kidding, I love this concept but I wish it were a bit lighter.', '2002-12-17 09:07:56.000000', NULL, 1),
(174171, 9679, 3859, '<td valign="top">So...are you the the one caught or doing the catching?  Interesting and creative shot.</td>', 'So...are you the the one caught or doing the catching?  Interesting and creative shot.', '2002-12-17 09:09:32.000000', NULL, 1),
(174174, 9763, 4648, '<td valign="top">I love this shot.  Obviously this is not you, because you are taking the photo, aren''t you.  You have a wonderful job.  I''ll substitute for you anyday.  And you are a greata photographer.  The shot through the windshield if awesome.  I like how you framed the photo and framed the outlet to the sea or lake with the land.  The sky is beautiful and the colors are beautiful.  Great 10 all day long.  PTL</td>', 'I love this shot.  Obviously this is not you, because you are taking the photo, aren''t you.  You have a wonderful job.  I''ll substitute for you anyday.  And you are a greata photographer.  The shot through the windshield if awesome.  I like how you framed the photo and framed the outlet to the sea or lake with the land.  The sky is beautiful and the colors are beautiful.  Great 10 all day long.  PTL', '2002-12-17 09:13:50.000000', NULL, 1),
(174175, 9767, 3859, '<td valign="top">This is a very interesting shot.  I like the B&amp;W.  I like the depth of field.  And I like the microphone right smack in the middle of the shot.  Forget the rule of thirds!  Sometimes this just works.  And it does here.</td>', 'This is a very interesting shot.  I like the B&W.  I like the depth of field.  And I like the microphone right smack in the middle of the shot.  Forget the rule of thirds!  Sometimes this just works.  And it does here.', '2002-12-17 09:14:11.000000', NULL, 1),
(174176, 9672, 3859, '<td valign="top">Hey, I''m going to have to look these up on Ebay.  Very neat item.  Good shot, too.</td>', 'Hey, I''m going to have to look these up on Ebay.  Very neat item.  Good shot, too.', '2002-12-17 09:15:09.000000', NULL, 1),
(174180, 9739, 4648, '<td valign="top">What wonderful depth.  The lighting is perfect to set the mood of the situation.  Love how you framed it with the walls and the windows at the end.  Some will say you should have cropped the top off the get closer to the people but that is crop.  Don''t change a thing.  Speaks millions as is.  Should place.  a 10 in my book.  PTL</td>', 'What wonderful depth.  The lighting is perfect to set the mood of the situation.  Love how you framed it with the walls and the windows at the end.  Some will say you should have cropped the top off the get closer to the people but that is crop.  Don''t change a thing.  Speaks millions as is.  Should place.  a 10 in my book.  PTL', '2002-12-17 09:17:39.000000', NULL, 1),
(174183, 9787, 4648, '<td valign="top">What a responsibility.  I love the colors - basiclly 2, blue and white.  This makes for a great photo.  Was going to say I''d like to see a little further down, but it looks like there might be cars there.  One thing that makes it for me is the limbs of the tree on the right side.  Just adds real life to the technology world.  Doesn''t take much to make me happy.  Because you added the tree I''ll add a point and give you a 9.  PTL</td>', 'What a responsibility.  I love the colors - basiclly 2, blue and white.  This makes for a great photo.  Was going to say I''d like to see a little further down, but it looks like there might be cars there.  One thing that makes it for me is the limbs of the tree on the right side.  Just adds real life to the technology world.  Doesn''t take much to make me happy.  Because you added the tree I''ll add a point and give you a 9.  PTL', '2002-12-17 09:22:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(174186, 9718, 4648, '<td valign="top">I have great respect for you, your photo, and your occupation.  You have two of my sons with you.   What an awesome idea of a way to display the uniform.  The texture is fantastic.  I love this cropping, the lighting, the composition.  You lost your focus a little at the bottom, but not enough to hurt anything - emotions did not distract my critique.  God bless you and God bless America.  This is worth a 10.  PTL</td>', 'I have great respect for you, your photo, and your occupation.  You have two of my sons with you.   What an awesome idea of a way to display the uniform.  The texture is fantastic.  I love this cropping, the lighting, the composition.  You lost your focus a little at the bottom, but not enough to hurt anything - emotions did not distract my critique.  God bless you and God bless America.  This is worth a 10.  PTL', '2002-12-17 09:26:57.000000', NULL, 1),
(174187, 9674, 4510, '<td valign="top">A very busy shot, well composed and beautifuly lit.</td>', 'A very busy shot, well composed and beautifuly lit.', '2002-12-17 09:31:03.000000', NULL, 1),
(174188, 9629, 4648, '<td valign="top">Great action shot.  Dredging the channel?  I love the depth to your photo with the land on the other side and the close up of the machinery.  The color of the machinery is great.  Maybe taken from another angle we could see the boat behind better, which would get rid of the distracting dark spot on the left side.  But the mud mixed with water flowing out of the bucket is just great.  I''ll give it an 8.  PTL</td>', 'Great action shot.  Dredging the channel?  I love the depth to your photo with the land on the other side and the close up of the machinery.  The color of the machinery is great.  Maybe taken from another angle we could see the boat behind better, which would get rid of the distracting dark spot on the left side.  But the mud mixed with water flowing out of the bucket is just great.  I''ll give it an 8.  PTL', '2002-12-17 09:32:30.000000', NULL, 1),
(174189, 9659, 4510, '<td valign="top">Great action shot and well composed, I like it.</td>', 'Great action shot and well composed, I like it.', '2002-12-17 09:34:23.000000', NULL, 1),
(174197, 9743, 4510, '<td valign="top">good use of colour and well composed, nice shot.</td>', 'good use of colour and well composed, nice shot.', '2002-12-17 10:02:46.000000', NULL, 1),
