(174722, 9658, 4411, '<td valign="top">The colour on this is fantastic, focus is spot on, composition is great. Well done.</td>', 'The colour on this is fantastic, focus is spot on, composition is great. Well done.', '2002-12-18 02:27:04.000000', NULL, 1),
(174723, 9813, 3900, '<td valign="top">OK, just what do you have against Frodo Baggins? :-)</td>', 'OK, just what do you have against Frodo Baggins? :-)', '2002-12-18 02:27:41.000000', NULL, 1),
(174725, 9690, 255, '<td valign="top">everything about this photo is fabulous---the clarity, the framing/composition and especially the lighting. awesome job!</td>', 'everything about this photo is fabulous---the clarity, the framing/composition and especially the lighting. awesome job!', '2002-12-18 02:31:13.000000', NULL, 1),
(174728, 9689, 4411, '<td valign="top">OMG, you can''t work there it looks way too cold!<br/>I like the lights on the water. I would probably have gone with a tighter crop on the pier myself, maybe shot so the trees at the front could be cut out completely.<br/>Still, a nice shot. It looks like you work in a beautiful (if cold) place.</td>', 'OMG, you can''t work there it looks way too cold!I like the lights on the water. I would probably have gone with a tighter crop on the pier myself, maybe shot so the trees at the front could be cut out completely.Still, a nice shot. It looks like you work in a beautiful (if cold) place.', '2002-12-18 02:37:09.000000', NULL, 1),
(174729, 9611, 4411, '<td valign="top">How on earth did you get your head lined up with the screen?! Nice shot, very creative.<br/>I''m not sure the books work well here, they''re probably too light and have blown out with the background. A good thick C/C++ book would have worked much better ; )</td>', 'How on earth did you get your head lined up with the screen?! Nice shot, very creative.I''m not sure the books work well here, they''re probably too light and have blown out with the background. A good thick C/C++ book would have worked much better ; )', '2002-12-18 02:43:23.000000', NULL, 1),
(174731, 9816, 3900, '<td valign="top">This is an interesting shot.  Very original.  Very nice focus, and just the right amount of stubble.  Probably good to keep it simple as opposed to maybe the middle finger, or a finger in each nostril.  Although you might want to open your mouth a bit more and show a little tongue.  The only other thing I can suggest is to crop out the eyelashes as it tends to make me want to see more of the eyes, therefore distracting from the mining.  Your wife must be proud. - 8</td>', 'This is an interesting shot.  Very original.  Very nice focus, and just the right amount of stubble.  Probably good to keep it simple as opposed to maybe the middle finger, or a finger in each nostril.  Although you might want to open your mouth a bit more and show a little tongue.  The only other thing I can suggest is to crop out the eyelashes as it tends to make me want to see more of the eyes, therefore distracting from the mining.  Your wife must be proud. - 8', '2002-12-18 02:44:43.000000', NULL, 1),
(174733, 9690, 4267, '<td valign="top">great lighting here....  not sure I like the angle though.... something like this with just the hand or the student with his head in his hands might be nice too :o)<br/> <br/>lol shows what I know.. looks like ya won the photo of the day at the other DPC, congratz! guess I will raise your score :o)<br/> <br/> if the contest was over I would give ya a congratz in the forums... but I am sure some wanker will bitch about it... good job!</td>', 'great lighting here....  not sure I like the angle though.... something like this with just the hand or the student with his head in his hands might be nice too :o) lol shows what I know.. looks like ya won the photo of the day at the other DPC, congratz! guess I will raise your score :o)  if the contest was over I would give ya a congratz in the forums... but I am sure some wanker will bitch about it... good job!', '2002-12-18 03:01:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(174734, 9688, 4267, '<td valign="top">is that a trick question? :o) great shot too!</td>', 'is that a trick question? :o) great shot too!', '2002-12-18 03:04:22.000000', NULL, 1),
(174741, 9606, 5023, '<td valign="top">Man, what a perfect sho,t love it  +9   This looks like the awesome style of one of my DA buddies  S.L.</td>', 'Man, what a perfect sho,t love it  +9   This looks like the awesome style of one of my DA buddies  S.L.', '2002-12-18 05:43:08.000000', NULL, 1),
(174744, 9631, 3732, '<td valign="top">very pretty</td>', 'very pretty', '2002-12-18 07:35:21.000000', NULL, 1),
(174750, 9656, 5158, '<td valign="top">Of all the keyboard-mouse images I like this most for it''s color and use of DOF.<br/>The reflection on the mouse turn out great colorwise. The thing in the upper part hower disturbs a little.</td>', 'Of all the keyboard-mouse images I like this most for it''s color and use of DOF.The reflection on the mouse turn out great colorwise. The thing in the upper part hower disturbs a little.', '2002-12-18 08:29:11.000000', NULL, 1),
(174753, 9770, 5158, '<td valign="top">I like this very much, although for itself the image is not recognized as "occupation".<br/>Could also be a little sharper, but I guess you had a hard time getting it focused anyway.</td>', 'I like this very much, although for itself the image is not recognized as "occupation".Could also be a little sharper, but I guess you had a hard time getting it focused anyway.', '2002-12-18 08:35:25.000000', NULL, 1),
(174756, 9599, 5158, '<td valign="top">Nice view, good background and pretty sharp. Probably you could have made it more intersting if you would have worked with the light a little better and it would also have been nice if a few of the LEDs were on.</td>', 'Nice view, good background and pretty sharp. Probably you could have made it more intersting if you would have worked with the light a little better and it would also have been nice if a few of the LEDs were on.', '2002-12-18 08:40:15.000000', NULL, 1),
(174758, 9771, 5158, '<td valign="top">I like the various colors and the gradient of the green. Also a wonderful collection of portraits you show to us.<br/>Of course, without title nobody would think it has something to do with "occupation", but that''s a problem of most submissions.<br/>Sad that one sees the white wall in the lower left corner.</td>', 'I like the various colors and the gradient of the green. Also a wonderful collection of portraits you show to us.Of course, without title nobody would think it has something to do with "occupation", but that''s a problem of most submissions.Sad that one sees the white wall in the lower left corner.', '2002-12-18 08:48:32.000000', NULL, 1),
(174759, 9773, 5158, '<td valign="top">It definitely fits to "occupation". I like the backgrounds color and brightness: very authentical. The composition could have been made better: two of the three students are at edges. But you probably didn''t have the time and possibility to do a lot of testing for your shot.<br/>That''s probably also the reason why the light on your face is not set too great.</td>', 'It definitely fits to "occupation". I like the backgrounds color and brightness: very authentical. The composition could have been made better: two of the three students are at edges. But you probably didn''t have the time and possibility to do a lot of testing for your shot.That''s probably also the reason why the light on your face is not set too great.', '2002-12-18 08:54:22.000000', NULL, 1),
(174762, 9795, 5158, '<td valign="top">I of course understand why you submitted this picture to DPC: this is a scene one (hopefully) does not see very often.And the way you captured with the bright flame, the black cloud in front of the dark blue sky is great. This would have been something for the photojournalism challenge.<br/>And the title you choosed was the best you could do for this submission.<br/>However, this great title (not used by anyone else)  calls for a long row of cars and the backlight. That would have been great.</td>', 'I of course understand why you submitted this picture to DPC: this is a scene one (hopefully) does not see very often.And the way you captured with the bright flame, the black cloud in front of the dark blue sky is great. This would have been something for the photojournalism challenge.And the title you choosed was the best you could do for this submission.However, this great title (not used by anyone else)  calls for a long row of cars and the backlight. That would have been great.', '2002-12-18 09:01:11.000000', NULL, 1),
(174764, 9666, 5158, '<td valign="top">Yummy!!<br/>Good idea!<br/>To make it look more tasteful, the light could have been set better. Using the flash gives all these bright reflections that result in a "greasy" look. Also the salad is too overexposed.</td>', 'Yummy!!Good idea!To make it look more tasteful, the light could have been set better. Using the flash gives all these bright reflections that result in a "greasy" look. Also the salad is too overexposed.', '2002-12-18 09:06:19.000000', NULL, 1),
(174766, 9609, 4648, '<td valign="top">This appears hazy to me.  I''d like a little more contrast.  I realize you are the expert photographer, but I know what I like to see.  To me it''s cropped a little to tightly.  To me this is a 6.  PTL</td>', 'This appears hazy to me.  I''d like a little more contrast.  I realize you are the expert photographer, but I know what I like to see.  To me it''s cropped a little to tightly.  To me this is a 6.  PTL', '2002-12-18 09:07:49.000000', NULL, 1),
(174767, 9665, 5158, '<td valign="top">The idea to show "shiney new cars" is great. But why didn''t you choose the showroom. there you would have had better light and not the disturbing snow that makes the whole picture look not very shiny at all.</td>', 'The idea to show "shiney new cars" is great. But why didn''t you choose the showroom. there you would have had better light and not the disturbing snow that makes the whole picture look not very shiny at all.', '2002-12-18 09:08:54.000000', NULL, 1),
(174769, 9631, 5158, '<td valign="top">Don''t get why this picture (even with title) should be linked to "occupation".</td>', 'Don''t get why this picture (even with title) should be linked to "occupation".', '2002-12-18 09:11:23.000000', NULL, 1),
(174771, 9737, 5158, '<td valign="top">Don''t get this one :(</td>', 'Don''t get this one :(', '2002-12-18 09:15:02.000000', NULL, 1),
(174772, 9716, 5158, '<td valign="top">Though a touch too overexposed, it would have made a nice entry for the technology challenge!<br/>But here?</td>', 'Though a touch too overexposed, it would have made a nice entry for the technology challenge!But here?', '2002-12-18 09:16:52.000000', NULL, 1),
(174776, 9602, 5158, '<td valign="top">Compared to the other "computer" submissions it shows a working place. Too overexposed though.</td>', 'Compared to the other "computer" submissions it shows a working place. Too overexposed though.', '2002-12-18 09:26:00.000000', NULL, 1),
(174779, 9817, 5158, '<td valign="top">That''s one of the few submissions showing somebody really working. Would have loved it, if the picture would be less "snap-shoty" and better composed.</td>', 'That''s one of the few submissions showing somebody really working. Would have loved it, if the picture would be less "snap-shoty" and better composed.', '2002-12-18 09:33:02.000000', NULL, 1),
(174781, 9691, 5158, '<td valign="top">Great idea, especially showing a shadow that long. But the upper part with the houses distract a little.</td>', 'Great idea, especially showing a shadow that long. But the upper part with the houses distract a little.', '2002-12-18 09:38:39.000000', NULL, 1),
(174793, 9682, 2058, '<td valign="top">I like the composition on this, but I think better lighting would greatly improve this photo, as well as a darker background.</td>', 'I like the composition on this, but I think better lighting would greatly improve this photo, as well as a darker background.', '2002-12-18 11:06:58.000000', NULL, 1),
(174799, 9645, 5100, '<td valign="top">nice concept but the picture itself is not good...</td>', 'nice concept but the picture itself is not good...', '2002-12-18 11:43:05.000000', NULL, 1),
(174806, 9701, 4495, '<td valign="top">The airplanes in the ceiling are very impressive</td>', 'The airplanes in the ceiling are very impressive', '2002-12-18 12:06:19.000000', NULL, 1),
(174846, 9818, 1005, '<td valign="top">While this does fit the challenge, and the photo is well taken, I''m not getting a strong "wow" sense from this photo.  Are you an insurance salesman?  (joke)  I would think this more effective if you included something in the way of hardware tool that helps these tools do their job (did that make sense?)  7 Swash</td>', 'While this does fit the challenge, and the photo is well taken, I''m not getting a strong "wow" sense from this photo.  Are you an insurance salesman?  (joke)  I would think this more effective if you included something in the way of hardware tool that helps these tools do their job (did that make sense?)  7 Swash', '2002-12-18 13:06:58.000000', NULL, 1),
(174851, 9816, 1005, '<td valign="top">Ever hear the phrase - get a job?  he he  It''s a fine pic, but honestly nothing near going on my wall, if you know what I mean.  Tell you what, you made me laugh, so I''ll bump your score one point.  6 Swash</td>', 'Ever hear the phrase - get a job?  he he  It''s a fine pic, but honestly nothing near going on my wall, if you know what I mean.  Tell you what, you made me laugh, so I''ll bump your score one point.  6 Swash', '2002-12-18 13:10:37.000000', NULL, 1),
(174856, 9751, 1005, '<td valign="top">Inverse image  - The photo does match the challenge, but seems very soft, not distinct, even the letter has soft edges.  6 Swash</td>', 'Inverse image  - The photo does match the challenge, but seems very soft, not distinct, even the letter has soft edges.  6 Swash', '2002-12-18 13:12:56.000000', NULL, 1),
(174860, 9813, 1005, '<td valign="top">I would hope a sniper would see a mor focused image.  I am curious how you got the burned look in the forehead, but I would think the laser sight would be in the middle of the scope, as in cross hairs (am I splitting hairs?)  5 Swash</td>', 'I would hope a sniper would see a mor focused image.  I am curious how you got the burned look in the forehead, but I would think the laser sight would be in the middle of the scope, as in cross hairs (am I splitting hairs?)  5 Swash', '2002-12-18 13:15:14.000000', NULL, 1),
(174867, 9762, 1005, '<td valign="top">For the setting, this is a pretty good picture.  But due to the low lighting (and the distance), the lecturer has almost no features.  The photo is surprisingly sharp, the overhead came out very well.  Score parly based on the difficulty of this shot.  7 Swash</td>', 'For the setting, this is a pretty good picture.  But due to the low lighting (and the distance), the lecturer has almost no features.  The photo is surprisingly sharp, the overhead came out very well.  Score parly based on the difficulty of this shot.  7 Swash', '2002-12-18 13:21:22.000000', NULL, 1),
(174870, 9645, 1005, '<td valign="top">This is a very sweet image, but the jpeg artifacts lessen the quality of the shot.  Good color.  7 Swash</td>', 'This is a very sweet image, but the jpeg artifacts lessen the quality of the shot.  Good color.  7 Swash', '2002-12-18 13:22:39.000000', NULL, 1),
(174877, 9750, 1005, '<td valign="top">While the focus is on the person (you?) with the camera, the "subject" seems as if it should be the flowers.  I see what you were doing here, but  I''m sorry, it doesn''t seem to work for me.  Add the glare from the window behind and the slight fuzziness (I believe from the mirror), not good.  6 Swash</td>', 'While the focus is on the person (you?) with the camera, the "subject" seems as if it should be the flowers.  I see what you were doing here, but  I''m sorry, it doesn''t seem to work for me.  Add the glare from the window behind and the slight fuzziness (I believe from the mirror), not good.  6 Swash', '2002-12-18 13:26:26.000000', NULL, 1),
(174884, 9657, 1005, '<td valign="top">The red wire is in great focus and demands attention, but the other side of the RJ45 connector is easier to see the wires (I think, cooler).  The slight turn causes reflections inside the housing that I don''t care for, more confusing to the viewer.    10 MB or 100MB?  7 Swash</td>', 'The red wire is in great focus and demands attention, but the other side of the RJ45 connector is easier to see the wires (I think, cooler).  The slight turn causes reflections inside the housing that I don''t care for, more confusing to the viewer.    10 MB or 100MB?  7 Swash', '2002-12-18 13:30:05.000000', NULL, 1),
(174889, 9596, 1005, '<td valign="top">Definately a cute title and pic, but it seems very small.  The dog with the glowing eyes is a nice touch.  This makes me smile.  The lines on the seats seem jagged, same with the man''s left sleeve, otherwise, really good focus.  7 Swash</td>', 'Definately a cute title and pic, but it seems very small.  The dog with the glowing eyes is a nice touch.  This makes me smile.  The lines on the seats seem jagged, same with the man''s left sleeve, otherwise, really good focus.  7 Swash', '2002-12-18 13:33:02.000000', NULL, 1),
(174894, 9745, 1005, '<td valign="top">This is a mouse, sitting on a photo of other mouse(s)!  At first, I thought the upper mouse was sitting on glass, but the glare patterns didn''t work!  (Photo mice have more side lighting, it appears to me.)  Photographed mouse(s) seem a tad grainy and dark.  This reminds me of my illusion shot.  7 Swash</td>', 'This is a mouse, sitting on a photo of other mouse(s)!  At first, I thought the upper mouse was sitting on glass, but the glare patterns didn''t work!  (Photo mice have more side lighting, it appears to me.)  Photographed mouse(s) seem a tad grainy and dark.  This reminds me of my illusion shot.  7 Swash', '2002-12-18 13:36:30.000000', NULL, 1),
(174897, 9778, 1005, '<td valign="top">Focus seems sharpest at the back of the picture.  I honestly don''t get it.  The club seems fairly sharp and the box in the back seems sharp, but the gauge in between isn''t at all.  7 Swash</td>', 'Focus seems sharpest at the back of the picture.  I honestly don''t get it.  The club seems fairly sharp and the box in the back seems sharp, but the gauge in between isn''t at all.  7 Swash', '2002-12-18 13:38:13.000000', NULL, 1),
(174899, 9688, 1005, '<td valign="top">I would have liked lots more contrast, maybe a darker background.  Sharp focus.  <br/>7 Swash</td>', 'I would have liked lots more contrast, maybe a darker background.  Sharp focus.  7 Swash', '2002-12-18 13:40:07.000000', NULL, 1),
(174900, 9653, 1005, '<td valign="top">Cute statue.  How about this idea  -  shoot this over the shoulder of the statue, with some "action" going on in front of it''s lens.  That would offer the viewer more interest and include an artistic addition that would make this piece fully yours.  The building background doesn''t work well, distracting from the lines of the statue.<br/>7 Swash</td>', 'Cute statue.  How about this idea  -  shoot this over the shoulder of the statue, with some "action" going on in front of it''s lens.  That would offer the viewer more interest and include an artistic addition that would make this piece fully yours.  The building background doesn''t work well, distracting from the lines of the statue.7 Swash', '2002-12-18 13:42:59.000000', NULL, 1),
(174901, 9823, 1005, '<td valign="top">Needs a sharper focus on the Compaq face.  Interest level is low for me (and I work with computers)  7 Swash</td>', 'Needs a sharper focus on the Compaq face.  Interest level is low for me (and I work with computers)  7 Swash', '2002-12-18 13:44:15.000000', NULL, 1),
(174902, 9632, 1005, '<td valign="top">So, are you a professional car rider?  (challenge theme?)  Interesting, but the glare on the windshield, ohhh.  Is this a VW cab?  7 Swash</td>', 'So, are you a professional car rider?  (challenge theme?)  Interesting, but the glare on the windshield, ohhh.  Is this a VW cab?  7 Swash', '2002-12-18 13:47:01.000000', NULL, 1),
(174906, 9794, 472, '<td valign="top">neat .. looks like dried spaghetti. :).  while it''s an interesting texture, the subject matter doesnt really have a lot of impact for me.  i assume that your occupation is something related to construction</td>', 'neat .. looks like dried spaghetti. :).  while it''s an interesting texture, the subject matter doesnt really have a lot of impact for me.  i assume that your occupation is something related to construction', '2002-12-18 14:11:29.000000', NULL, 1),
(174907, 9616, 472, '<td valign="top">cute.  but santa i thought you were supposed to be jolly. you''re not smiling at all!  and you sure have lost a lot of weight too.  and are those your real glasses?????</td>', 'cute.  but santa i thought you were supposed to be jolly. you''re not smiling at all!  and you sure have lost a lot of weight too.  and are those your real glasses?????', '2002-12-18 14:12:15.000000', NULL, 1),
(174909, 9802, 472, '<td valign="top">not sure why the selective desat. i dont think it adds.</td>', 'not sure why the selective desat. i dont think it adds.', '2002-12-18 14:13:13.000000', NULL, 1),
(174910, 9640, 472, '<td valign="top">i bet it''s stll fun to play oncein a while :) .. seriously, nice shot.</td>', 'i bet it''s stll fun to play oncein a while :) .. seriously, nice shot.', '2002-12-18 14:13:48.000000', NULL, 1),
(174911, 9596, 472, '<td valign="top">i like the dog looking up at the pic.</td>', 'i like the dog looking up at the pic.', '2002-12-18 14:14:01.000000', NULL, 1),
(174912, 9606, 472, '<td valign="top">you must be a person of many talents. i like the colors.</td>', 'you must be a person of many talents. i like the colors.', '2002-12-18 14:14:48.000000', NULL, 1),
(174913, 9737, 472, '<td valign="top">nice fall colors but there is a weird cyan color cast on this pic.</td>', 'nice fall colors but there is a weird cyan color cast on this pic.', '2002-12-18 14:15:06.000000', NULL, 1),
(174914, 9811, 472, '<td valign="top">wish i had that view.</td>', 'wish i had that view.', '2002-12-18 14:15:21.000000', NULL, 1),
(174915, 9690, 472, '<td valign="top">my friend''s gf used to work at rainforest cafe. we would get freebies. i liked the coconut chicken.  the subtle lighting on this image works well.</td>', 'my friend''s gf used to work at rainforest cafe. we would get freebies. i liked the coconut chicken.  the subtle lighting on this image works well.', '2002-12-18 14:16:38.000000', NULL, 1),
(174916, 9665, 472, '<td valign="top">do you sell them? can i have one? :) ill take silver.</td>', 'do you sell them? can i have one? :) ill take silver.', '2002-12-18 14:17:05.000000', NULL, 1),
(174917, 9816, 472, '<td valign="top">i recognize this person i think.  if it''s who i think it is, i guess you DO have a lot of time on your hands! as an image, it''s a good bw and the focus is great.  what channel mixer settings do you use?</td>', 'i recognize this person i think.  if it''s who i think it is, i guess you DO have a lot of time on your hands! as an image, it''s a good bw and the focus is great.  what channel mixer settings do you use?', '2002-12-18 14:18:45.000000', NULL, 1),
(174918, 9735, 472, '<td valign="top">you work at an airport?</td>', 'you work at an airport?', '2002-12-18 14:19:20.000000', NULL, 1),
(174919, 9736, 472, '<td valign="top">good shape!</td>', 'good shape!', '2002-12-18 14:19:30.000000', NULL, 1),
(174920, 9686, 472, '<td valign="top">much too dark.</td>', 'much too dark.', '2002-12-18 14:19:56.000000', NULL, 1),
(174921, 9826, 472, '<td valign="top">nice altho there is a reddish color cast.</td>', 'nice altho there is a reddish color cast.', '2002-12-18 14:20:13.000000', NULL, 1),
(174922, 9659, 472, '<td valign="top">u were a pro golfer? this is a well done image. would have worked well for motion. the light on the ball is too glary, a bit blown out.</td>', 'u were a pro golfer? this is a well done image. would have worked well for motion. the light on the ball is too glary, a bit blown out.', '2002-12-18 14:20:48.000000', NULL, 1),
