(174927, 9770, 472, '<td valign="top">cool.  poor focus lets down what could have been an outstanding shot unfortunately....</td>', 'cool.  poor focus lets down what could have been an outstanding shot unfortunately....', '2002-12-18 14:22:47.000000', NULL, 1),
(174928, 9823, 472, '<td valign="top">too busy and unclear what the subject of the pic is. i dont like the blurred mouse in the foreground.</td>', 'too busy and unclear what the subject of the pic is. i dont like the blurred mouse in the foreground.', '2002-12-18 14:23:41.000000', NULL, 1),
(174929, 9710, 472, '<td valign="top">a bit oversharpened it looks like...</td>', 'a bit oversharpened it looks like...', '2002-12-18 14:24:07.000000', NULL, 1),
