(175508, 9638, 5351, '<td valign="top">Really nice photo - i like the composition, focus.</td>', 'Really nice photo - i like the composition, focus.', '2002-12-19 20:47:47.000000', NULL, 1),
(175513, 9658, 737, '<td valign="top">I don''t know if you make them or drink them - but I do know this is the best photo here. Print it and frame it - a 10.<br/> <br/>Jim msp</td>', 'I don''t know if you make them or drink them - but I do know this is the best photo here. Print it and frame it - a 10. Jim msp', '2002-12-19 21:39:05.000000', NULL, 1),
(175520, 9591, 3447, '<td valign="top">It would have been good to crop white article at right.  Good action photo.</td>', 'It would have been good to crop white article at right.  Good action photo.', '2002-12-19 22:08:39.000000', NULL, 1),
(175526, 9799, 1280, '<td valign="top">This is a very cool picture but I wonder why you didn''t turn the camera to portrait, rather than landscape.  It would have suited the subject better.</td>', 'This is a very cool picture but I wonder why you didn''t turn the camera to portrait, rather than landscape.  It would have suited the subject better.', '2002-12-19 22:15:37.000000', NULL, 1),
(175530, 9638, 1280, '<td valign="top">Lovely image.  I am trying to identify this bird.  It looks like a game bird.  My first thought is a Ptarmigan???  Beautiful markings, and a cute tuft, well captured. Nice catchlight in the eye too. I''m still trying to id this one.  Whip Poor Will?  Chuck Will''s Widow?  Night Hawk?</td>', 'Lovely image.  I am trying to identify this bird.  It looks like a game bird.  My first thought is a Ptarmigan???  Beautiful markings, and a cute tuft, well captured. Nice catchlight in the eye too. I''m still trying to id this one.  Whip Poor Will?  Chuck Will''s Widow?  Night Hawk?', '2002-12-19 22:32:08.000000', NULL, 1),
(175537, 9646, 1280, '<td valign="top">I have no idea what this has to do with your occupation but I love this picture.  What a sweet little pink and white funny face.  I love it!!! Are you a Cat groomer?</td>', 'I have no idea what this has to do with your occupation but I love this picture.  What a sweet little pink and white funny face.  I love it!!! Are you a Cat groomer?', '2002-12-19 23:13:17.000000', NULL, 1),
(175539, 9736, 4007, '<td valign="top">Nice framing, black background works well.. simple subject made interesting.  Nothing earth-shattering but a very likable photo. 7</td>', 'Nice framing, black background works well.. simple subject made interesting.  Nothing earth-shattering but a very likable photo. 7', '2002-12-19 23:16:43.000000', NULL, 1),
(175540, 9750, 1280, '<td valign="top">I love the inclusion of the tulips.  Makes a wonderfully interesting foreground.</td>', 'I love the inclusion of the tulips.  Makes a wonderfully interesting foreground.', '2002-12-19 23:18:54.000000', NULL, 1),
(175541, 9600, 4007, '<td valign="top">I like the expression on his face.  I like the concept.  The large empty space at top left seems to be a problem.  I''m not sure how you could do the shot without leaving that hole. Perhaps trimming some of the left and top boarders would help.  6</td>', 'I like the expression on his face.  I like the concept.  The large empty space at top left seems to be a problem.  I''m not sure how you could do the shot without leaving that hole. Perhaps trimming some of the left and top boarders would help.  6', '2002-12-19 23:20:07.000000', NULL, 1),
(175542, 9658, 4007, '<td valign="top">The colors and general tone of this photo really appeal to me.  Good call with the thin black boarder as well.  Great shot. 9</td>', 'The colors and general tone of this photo really appeal to me.  Good call with the thin black boarder as well.  Great shot. 9', '2002-12-19 23:21:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(175544, 9760, 1280, '<td valign="top">Very odd angle of these manequiines.</td>', 'Very odd angle of these manequiines.', '2002-12-19 23:31:32.000000', NULL, 1),
(175547, 9689, 1280, '<td valign="top">A harbor master?  Lovely scene.</td>', 'A harbor master?  Lovely scene.', '2002-12-19 23:33:32.000000', NULL, 1),
(175549, 9662, 1280, '<td valign="top">I used to take care of a quadriplegic friend.  Good, honest, helpful work.  <br/>The picture is a little cluttered.</td>', 'I used to take care of a quadriplegic friend.  Good, honest, helpful work.  The picture is a little cluttered.', '2002-12-19 23:36:26.000000', NULL, 1),
(175553, 9695, 1280, '<td valign="top">Good job of portrayng...your picture tells the story.  Technically also good.  Just enough motion in the hand.</td>', 'Good job of portrayng...your picture tells the story.  Technically also good.  Just enough motion in the hand.', '2002-12-19 23:41:06.000000', NULL, 1),
(175556, 9807, 1280, '<td valign="top">Very nice job!</td>', 'Very nice job!', '2002-12-19 23:43:56.000000', NULL, 1),
(175557, 9770, 1280, '<td valign="top">Beautiful job!!  Great composition, brillian colors, fluid motion.  I like it very much.</td>', 'Beautiful job!!  Great composition, brillian colors, fluid motion.  I like it very much.', '2002-12-19 23:57:39.000000', NULL, 1),
(175558, 9811, 1280, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2002-12-19 23:58:25.000000', NULL, 1),
(175577, 9792, 5627, '<td valign="top">At first glance the lack of focus bothered me.  But after reflecting for a moment back to my college days, I remember many bleary eyed nights when the text books looked just like this.  Nice.</td>', 'At first glance the lack of focus bothered me.  But after reflecting for a moment back to my college days, I remember many bleary eyed nights when the text books looked just like this.  Nice.', '2002-12-20 01:02:19.000000', NULL, 1),
(175586, 9615, 4767, '<td valign="top">A six-twenty film camera represents your occupation?   AHHHH!  You sell antiques!  COOL!<br/> <br/></td>', 'A six-twenty film camera represents your occupation?   AHHHH!  You sell antiques!  COOL! ', '2002-12-20 02:15:56.000000', NULL, 1),
(175596, 9799, 5681, '<td valign="top">I can understand you off-centering this because of the multitude of comments I see on this site about the rule-of-thirds, but I see no point here.  There is no background, hence there is no reason for off-centering, why the pointless black space on the left?.  And the subject is too large to fit in any "third" region, therefore it looks like you were drunk and just misqueued.  However I do like the subject, whatever it is, and it is nicely focussed, but I really wish it was centered.</td>', 'I can understand you off-centering this because of the multitude of comments I see on this site about the rule-of-thirds, but I see no point here.  There is no background, hence there is no reason for off-centering, why the pointless black space on the left?.  And the subject is too large to fit in any "third" region, therefore it looks like you were drunk and just misqueued.  However I do like the subject, whatever it is, and it is nicely focussed, but I really wish it was centered.', '2002-12-20 03:42:04.000000', NULL, 1),
(175597, 9816, 5681, '<td valign="top">Digging for gold, no doubt.  Best of luck to you.  I hope you get some juicy nuggets.  :-)  Hehe, anyway, nice clear photo.</td>', 'Digging for gold, no doubt.  Best of luck to you.  I hope you get some juicy nuggets.  :-)  Hehe, anyway, nice clear photo.', '2002-12-20 03:46:22.000000', NULL, 1),
(175598, 9807, 5681, '<td valign="top">Wow, that looks very intricate and time-consuming and talented, and not a bad shot.  I just wish the whole photo was the one you''re drawing on.  The other one in the foreground is very distracting.</td>', 'Wow, that looks very intricate and time-consuming and talented, and not a bad shot.  I just wish the whole photo was the one you''re drawing on.  The other one in the foreground is very distracting.', '2002-12-20 03:49:58.000000', NULL, 1),
(175599, 9611, 5681, '<td valign="top">WOW, what a geek! :-)  Just kidding.  I think I might be one too.  But, cool shot.</td>', 'WOW, what a geek! :-)  Just kidding.  I think I might be one too.  But, cool shot.', '2002-12-20 03:51:55.000000', NULL, 1),
(175609, 9773, 3540, '<td valign="top">Self portrait albright?</td>', 'Self portrait albright?', '2002-12-20 05:00:12.000000', NULL, 1),
(175610, 9795, 5023, '<td valign="top">very very cool shot.  but are you a commuter or a fireman,  or a commuting fireman?  anyways..goood score for this one</td>', 'very very cool shot.  but are you a commuter or a fireman,  or a commuting fireman?  anyways..goood score for this one', '2002-12-20 05:22:49.000000', NULL, 1),
