(176373, 9674, 5044, '<td valign="top">Is that a beer bottle? Not on the job, I hope...</td>', 'Is that a beer bottle? Not on the job, I hope...', '2002-12-22 20:23:13.000000', NULL, 1),
(176377, 9747, 2716, '<td valign="top">Mmmm ... beer!  Sounds like the dream job.  Nice shot.  8  Jacko</td>', 'Mmmm ... beer!  Sounds like the dream job.  Nice shot.  8  Jacko', '2002-12-22 21:16:23.000000', NULL, 1),
(176378, 9675, 2716, '<td valign="top">Nice package.</td>', 'Nice package.', '2002-12-22 21:16:40.000000', NULL, 1),
